NUS_SVC = "6e400001-b5a3-f393-e0a9-e50e24dcca9e"
NUS_TX  = "6e400003-b5a3-f393-e0a9-e50e24dcca9e"

# BLE packet: a sample count byte, then that many samples. Must match Sample in src/main.cpp.
SAMPLE_STRUCT = struct.Struct('<IH6H6h')  # board ms, seq, 6 ADC, ax ay az gx gy gz
MAX_PACKET_SAMPLES = 8                    # below '\n', so never confused with old firmware's text
ADC_TO_V = 3.3/4095
ACC_TO_G = 0.000122                       # LSM6DS3 at +-4 g
GYRO_TO_DPS = 0.07                        # LSM6DS3 at +-2000 deg/s

POS_R = [(18.9,8.2),(17,28.5),(85.7,28.7),(83.4,52.3),(26.6,54.3),(56.1,89)]
POS_L = [(100-x, y) for x,y in POS_R]

COLORS     = ["#D84506","#2B90D8","#1D9E33","#E59D38","#7C46C8","#EC1885"]
IMU_C      = {'ax':'#D84506','ay':'#2B90D8','az':'#1D9E33','gx':'#E59D38','gy':'#7C46C8','gz':'#EC1885'}
ACC_KEYS   = ['ax','ay','az']
GYRO_KEYS  = ['gx','gy','gz']
IMU_KEYS   = ACC_KEYS + GYRO_KEYS
MAXPTS     = 150
BG         = QColor(28,28,26)
CARD_BG    = QColor(36,36,34)
BORDER     = QColor(60,60,58)
BAR_W      = 12   # balance colour bars around the foot map
BAR_GAP    = 4
BAR_SPACE  = BAR_W + BAR_GAP
ARROW_C    = QColor("#CCFF26")
# side view: board standing at the ankle, x vertical, rotating about z (measured 2026-11-01)
SIDE_TILT_Y    = 'ax'  # the tilt angle is atan2(SIDE_TILT_Y, SIDE_TILT_X), which turns at +gz
SIDE_TILT_X    = 'ay'
SIDE_PITCH_GYRO = 'gz'
SIDE_TOES_UP   = {'L': -1, 'R': 1}  # flip for a foot whose view turns the wrong way
SIDE_DT        = 0.02  # s between samples
SIDE_TILT_MIX  = 0.98  # share of each angle update taken from the gyro
SIDE_UP_ACC    = 'ax'  # the vertical board axis
SIDE_UP_SIGN   = -1    # -x points up with the board standing at the ankle
SIDE_MAX_LIFT  = 0.30  # m shown at the top of the view
SIDE_LIFT_HOLD = 0.999 # height kept per sample at rest, about a 20 s time constant at 50 Hz
SIDE_REST_ACC  = 0.05  # g from 1 g, and
SIDE_REST_GYRO = 30    # deg/s, below which the foot counts as still
WEIGHT_MAX_DIFF = 20   # percentage points between feet before the bar turns red and blue
ZERO_WINDOW    = 50    # frames the pressure zero is measured over, 1 s at 50 Hz
# one row per frame received from one foot, so a dropout shows up as a gap in that foot's rows
RECORD_HEADER_V2 = ['t','foot'] + [f'S{i+1}' for i in range(6)] + IMU_KEYS
RECORD_HEADER = ['t','foot','seq','board_ms'] + RECORD_HEADER_V2[2:]
LEGACY_RECORD_HEADER = ['t'] + [f'{side}_{k}' for side in ('L','R')
                                for k in [f'S{i+1}' for i in range(6)] + IMU_KEYS]

def decode_packet(data):
    """Split a BLE packet into (seq, board_ms, vals, imu) samples, ignoring any truncated tail."""
    samples = []
    count = min(data[0], (len(data)-1)//SAMPLE_STRUCT.size)
    for i in range(count):
        ms, seq, *raw = SAMPLE_STRUCT.unpack_from(data, 1+i*SAMPLE_STRUCT.size)
        vals = [v*ADC_TO_V for v in raw[:6]]
        imu = {k: v*ACC_TO_G for k,v in zip(ACC_KEYS,raw[6:9])}
        imu.update({k: v*GYRO_TO_DPS for k,v in zip(GYRO_KEYS,raw[9:])})
        samples.append((seq, ms, vals, imu))
    return samples

def load_positions():
    """Saved sensor positions, or the defaults if none are saved or they are unusable."""
    try:
        saved = json.loads(QSettings('xiao-pressure','monitor').value('positions', '') or '{}')
        pl = [[float(x),float(y)] for x,y in saved['L']]
        pr = [[float(x),float(y)] for x,y in saved['R']]
        if len(pl)==6 and len(pr)==6: return pl, pr
    except (ValueError, TypeError, KeyError):
        pass
    return POS_L, POS_R

def save_positions(pos_l, pos_r):
    QSettings('xiao-pressure','monitor').setValue('positions', json.dumps({'L':pos_l,'R':pos_r}))

def load_recording(path):
    """Read a recording into time-ordered (t, side, vals, imu) frames. Raises ValueError if malformed."""
    with open(path, newline='') as f:
        reader = csv.reader(f)
        header = next(reader, None)
        rows = [row for row in reader if row]
    if header in (RECORD_HEADER, RECORD_HEADER_V2):
        s1 = header.index('S1')
        frames = []
        for row in rows:
            if len(row)!=len(header) or row[1] not in ('L','R'):
                raise ValueError(f"unexpected row: {row}")
            imu = {k: float(x) for k,x in zip(IMU_KEYS,row[s1+6:]) if x}
            frames.append((float(row[0]), row[1], [float(x) for x in row[s1:s1+6]], imu))
    elif header == LEGACY_RECORD_HEADER:
        # older files: one wide row per GUI tick, both feet side by side
        frames = []
        for row in rows:
            if len(row)!=len(LEGACY_RECORD_HEADER):
                raise ValueError(f"unexpected row: {row}")
            for pos,side in ((1,'L'),(13,'R')):
                imu = {k: float(x) for k,x in zip(IMU_KEYS,row[pos+6:pos+12])}
                frames.append((float(row[0]), side, [float(x) for x in row[pos:pos+6]], imu))
    else:
        raise ValueError("not a recording from this app (unknown columns)")
    frames.sort(key=lambda f: f[0])
    return frames

def heat_color(t, alpha=1.0):
    t = max(0.0, min(1.0, t))
    if t < 0.5:
        u = t*2; r=int(230+(55-230)*u); g=int(241+(138-241)*u); b=int(251+(221-251)*u)
    else:
        u=(t-0.5)*2; r=int(55+(226-55)*u); g=int(138+(75-138)*u); b=int(221+(74-221)*u)
    return QColor(r,g,b,int(alpha*255))

# ── Serial Worker ──────────────────────────────────────────────
class SerialWorker(QObject):
    line_received = pyqtSignal(str, float)
    status        = pyqtSignal(str, bool)

    def __init__(self, port):
        super().__init__()
        self.port = port
        self._running = False
        self._ser = None

    def run(self):
        self._running = True
        error = None
        try:
            self._ser = serial.Serial(self.port, 115200, timeout=0.1)
            self.status.emit(f"Serial {self.port}", True)
            buf = ""
            while self._running:
                # read what has arrived; a fixed size would hold lines back until the timeout
                data = self._ser.read(self._ser.in_waiting or 1).decode('utf-8', errors='ignore')
                if data:
                    t = time.perf_counter()
                    buf += data
                    while '\n' in buf:
                        line, buf = buf.split('\n', 1)
                        line = line.strip()
                        if line: self.line_received.emit(line, t)
        except Exception as e:
            error = f"Error: {e}"
        finally:
            if self._ser:
                try: self._ser.close()
                except: pass
            self.status.emit(error or "Disconnected", False)

    def stop(self):
        self._running = False

# ── BLE Worker ────────────────────────────────────────────────
class BLEWorker(QObject):
    line_received  = pyqtSignal(str, float)
    samples_received = pyqtSignal(list, float)
    status         = pyqtSignal(str, bool)
    devices_found  = pyqtSignal(list)

    def __init__(self):
        super().__init__()
        self._client = None
        self._running = False

    def scan(self):
        def _run():
            loop = asyncio.new_event_loop()
            try:
                devs = loop.run_until_complete(BleakScanner.discover(timeout=5.0))
                result = [(d.name, d.address) for d in devs if d.name and 'Pressure' in d.name]
                self.devices_found.emit(result)
            except Exception as e:
                self.devices_found.emit([])
                self.status.emit(f"BLE scan error: {e}", False)
            finally:
                loop.close()
        threading.Thread(target=_run, daemon=True).start()

    def connect_device(self, address):
        self._running = True
        def _run():
            loop = asyncio.new_event_loop()
            loop.run_until_complete(self._connect(address))
            loop.close()
        threading.Thread(target=_run, daemon=True).start()

    async def _connect(self, address):
        buf = ""
        error = None
        def handler(sender, data):
            nonlocal buf
            t = time.perf_counter()
            if data and data[0] <= MAX_PACKET_SAMPLES:
                self.samples_received.emit(decode_packet(data), t)
                return
            buf += data.decode('utf-8', errors='ignore')
            while '\n' in buf:
                line, buf = buf.split('\n', 1)
                line = line.strip()
                if line: self.line_received.emit(line, t)
        try:
            self._client = BleakClient(address)
            await self._client.connect()
            self.status.emit(f"BLE {address[:8]}…", True)
            await self._client.start_notify(NUS_TX, handler)
            while self._running and self._client.is_connected:
                await asyncio.sleep(0.1)
        except Exception as e:
            error = f"BLE error: {e}"
        finally:
            if self._client:
                try: await self._client.disconnect()
                except: pass
            self.status.emit(error or "Disconnected", False)

    def stop(self):
        self._running = False

# ── Device Picker Dialog ───────────────────────────────────────
class DevicePickerDialog(QDialog):
    def __init__(self, devices, parent=None):
        super().__init__(parent)
        self.setWindowTitle("Select Device")
        self.chosen = None
        layout = QVBoxLayout(self)
        self.list = QListWidget()
        for name, addr in devices:
            item = QListWidgetItem(f"{name}  [{addr}]")
            item.setData(Qt.ItemDataRole.UserRole, (name, addr))
            self.list.addItem(item)
        self.list.doubleClicked.connect(self.accept)
        layout.addWidget(QLabel("Select a Pressure device:"))
        layout.addWidget(self.list)
        btns = QDialogButtonBox(QDialogButtonBox.StandardButton.Ok | QDialogButtonBox.StandardButton.Cancel)
        btns.accepted.connect(self.accept)
        btns.rejected.connect(self.reject)
        layout.addWidget(btns)

    def accept(self):
        item = self.list.currentItem()
        if item:
            self.chosen = item.data(Qt.ItemDataRole.UserRole)
        super().accept()

# ── Foot Heatmap Widget ────────────────────────────────────────
class FootWidget(QWidget):
    clicked = pyqtSignal(float, float)  # x%, y%

    def __init__(self, side, pos_list):
        super().__init__()
        self.side = side
        self.pos = pos_list
        self.vals = [0.0]*6
        self.trail = deque(maxlen=80)
        self.setup_mode = False
        img_data = base64.b64decode(LEFT_B64 if side == 'L' else RIGHT_B64)
        self._foot_img = QImage.fromData(img_data)
        self.setMinimumSize(150+BAR_SPACE, 340+BAR_SPACE)
        self.setMaximumWidth(200+BAR_SPACE)
        self.setCursor(QCursor(Qt.CursorShape.CrossCursor))
        self._scaled_foot = None
        self._scaled_size = None
        self._scaled_offset = (0, 0)

    def _update_scaled_image(self):
        W, H = self.width()-BAR_SPACE, self.height()-BAR_SPACE

        if self._foot_img.isNull():
            self._scaled_foot = None
            return

        current_size = (W, H)

        # size 没变就不重新缩放
        if (self._scaled_foot is not None 
            and self._scaled_size == current_size):
            return

        scaled = self._foot_img.scaled(
            W,
            H,
            Qt.AspectRatioMode.KeepAspectRatio,
            Qt.TransformationMode.SmoothTransformation
        )

        xo = (W - scaled.width()) // 2 + (BAR_SPACE if self.side == 'L' else 0)
        yo = (H - scaled.height()) // 2

        self._scaled_foot = scaled
        self._scaled_size = current_size
        self._scaled_offset = (xo, yo)

    def update_vals(self, vals):
        self.vals = vals[:]

        weights = [3.5, 2.0, 2.0, 1.0, 1.0, 2]
        weighted_vals = [
            max(vals[i], 0) * weights[i]
            for i in range(6)
        ]

        tw = sum(weighted_vals)

        if tw > 0.01:
            cx = sum(
                self.pos[i][0] * weighted_vals[i]
                for i in range(6)
            ) / tw

            cy = sum(
                self.pos[i][1] * weighted_vals[i]
                for i in range(6)
            ) / tw

            self.trail.append((cx / 100, cy / 100))

        self.update()

    def clear_cop(self):
        self.trail.clear()
        self.update()

    def _img_rect(self):
        self._update_scaled_image()

        if self._scaled_foot is None:
            return 0, 0, self.width(), self.height()

        xo, yo = self._scaled_offset

        return (
            xo,
            yo,
            self._scaled_foot.width(),
            self._scaled_foot.height()
        )

    def resizeEvent(self, event):
        self._scaled_foot = None
        self._scaled_size = None
        super().resizeEvent(event)

    def mousePressEvent(self, e):
        if not self.setup_mode: return
        xo,yo,iW,iH = self._img_rect()
        px = (e.position().x()-xo)/iW*100
        py = (e.position().y()-yo)/iH*100
        if not (0<=px<=100 and 0<=py<=100): return
        self.clicked.emit(px, py)

    def paintEvent(self, event):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        W,H = self.width(),self.height()
        p.fillRect(0,0,W,H,BG)
        if self._foot_img.isNull(): return
        xo,yo,iW,iH = self._img_rect()
        p.drawImage(xo,yo,self._scaled_foot)
        # heatmap blobs
        for i,(px,py) in enumerate(self.pos):
            cx = xo+px/100*iW; cy = yo+py/100*iH
            t = max(0,min(1,self.vals[i]/2.3))
            R = int(iW*0.18)
            for r in range(R,0,-4):
                c = heat_color(t,(1-r/R)*0.65)
                p.setBrush(QBrush(c)); p.setPen(Qt.PenStyle.NoPen)
                p.drawEllipse(int(cx-r),int(cy-r),r*2,r*2)
        # COP trail
        trail = list(self.trail)
        for i in range(1,len(trail)):
            a = i/len(trail)*0.7
            p.setPen(QPen(QColor(255,215,0,int(a*255)),2))
            p.drawLine(int(xo+trail[i-1][0]*iW),int(yo+trail[i-1][1]*iH),
                       int(xo+trail[i][0]*iW),  int(yo+trail[i][1]*iH))
        if trail:
            cx=xo+trail[-1][0]*iW; cy=yo+trail[-1][1]*iH
            p.setBrush(QBrush(QColor(255,215,0,220)))
            p.setPen(QPen(QColor(255,255,255,180),1.5))
            p.drawEllipse(int(cx-5),int(cy-5),10,10)
        # sensor labels
        p.setFont(QFont('Arial',11,QFont.Weight.Bold))
        fm = p.fontMetrics()
        for i,(px,py) in enumerate(self.pos):
            cx=xo+px/100*iW; cy=yo+py/100*iH
            text = f"S{i+1}"
            p.setPen(QPen(QColor(COLORS[i])))
            p.drawText(int(cx-fm.horizontalAdvance(text)/2),int(cy+fm.capHeight()/2),text)
        self._paint_balance(p,xo,yo,iW,iH)

    def _paint_balance(self, p, xo, yo, iW, iH):
        """Colour bars on the outer side and below the foot, with arrows from the COP to each."""
        bx = xo-BAR_SPACE if self.side=='L' else xo+iW+BAR_GAP
        by = yo+iH+BAR_GAP
        self._paint_bar(p, bx, yo, BAR_W, iH, True)
        self._paint_bar(p, xo, by, iW, BAR_W, False)
        if not self.trail: return
        cx=xo+self.trail[-1][0]*iW; cy=yo+self.trail[-1][1]*iH
        self._paint_arrow(p, cx, cy, bx+BAR_W if self.side=='L' else bx, cy)
        self._paint_arrow(p, cx, cy, cx, by)

    def _paint_bar(self, p, x, y, w, h, vertical):
        """Bright at the middle of the foot, fading into the background towards either end."""
        grad = QLinearGradient(x, y, x, y+h) if vertical else QLinearGradient(x, y, x+w, y)
        grad.setColorAt(0.0, QColor('#2A3440'))
        grad.setColorAt(0.5, QColor('#378ADD'))
        grad.setColorAt(1.0, QColor('#2A3440'))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QBrush(grad))
        p.drawRect(x, y, w, h)
        p.setPen(QPen(Qt.GlobalColor.white, 1))
        if vertical: p.drawLine(x, y+h//2, x+w, y+h//2)
        else: p.drawLine(x+w//2, y, x+w//2, y+h)

    def _paint_arrow(self, p, x1, y1, x2, y2):
        p.setPen(QPen(ARROW_C, 2))
        p.drawLine(QPointF(x1,y1), QPointF(x2,y2))
        dx = (x2>x1)-(x2<x1); dy = (y2>y1)-(y2<y1)  # the arrows are always axis aligned
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QBrush(ARROW_C))
        p.drawPolygon(QPolygonF([QPointF(x2,y2),
                                 QPointF(x2-8*dx-4*dy, y2-8*dy-4*dx),
                                 QPointF(x2-8*dx+4*dy, y2-8*dy+4*dx)]))



# ── Foot Side View ─────────────────────────────────────────────
def wrap_deg(a):
    return (a+180)%360-180

class FootSideView(QFrame):
    """Side view of the foot: turned by pitch, raised by a double integral of vertical acceleration."""

    def __init__(self, side):
        super().__init__()
        self.side = side
        self.setMinimumHeight(150)
        self.setCursor(QCursor(Qt.CursorShape.PointingHandCursor))
        self.setToolTip("Click to set the current pose as flat")
        self.reset()

        foot = QPainterPath()
        foot.moveTo(8,0); foot.lineTo(88,0)
        foot.cubicTo(100,0, 102,-8, 92,-11)
        foot.cubicTo(70,-16, 52,-26, 40,-44)
        foot.lineTo(40,-62); foot.lineTo(12,-62); foot.lineTo(12,-30)
        foot.cubicTo(10,-20, -2,-16, 0,-8)
        foot.cubicTo(0,-3, 3,0, 8,0)
        self.foot = foot

    def reset(self):
        self.pitch = None
        self.zero = 0.0
        self.vel = 0.0
        self.lift = 0.0
        self.update()

    def update_imu(self, imu):
        if not all(k in imu for k in IMU_KEYS): return
        tilt = math.degrees(math.atan2(imu[SIDE_TILT_Y], imu[SIDE_TILT_X]))
        if self.pitch is None:
            self.pitch = self.zero = tilt
        self.pitch += imu[SIDE_PITCH_GYRO]*SIDE_DT
        self.pitch += (1-SIDE_TILT_MIX)*wrap_deg(tilt-self.pitch)

        # what is left of the vertical axis once gravity at the current tilt is taken out
        in_plane = math.sqrt(max(0.0, 1-imu['az']**2))
        gravity = in_plane*math.sin(math.radians(self.pitch))
        up = SIDE_UP_SIGN*(imu[SIDE_UP_ACC]-gravity)  # g
        norm = math.sqrt(sum(imu[k]**2 for k in ACC_KEYS))
        gyro = math.sqrt(sum(imu[k]**2 for k in GYRO_KEYS))
        if abs(norm-1)<SIDE_REST_ACC and gyro<SIDE_REST_GYRO:
            self.vel = 0.0  # still, so any velocity left is integration error
            self.lift *= SIDE_LIFT_HOLD
        else:
            self.vel = (self.vel+up*9.81*SIDE_DT)*0.995
            # velocity is kept at the limits, or the braking half of a move would push the foot back
            self.lift = max(0.0, min(SIDE_MAX_LIFT, self.lift+self.vel*SIDE_DT))
        self.update()

    def mousePressEvent(self, e):
        if self.pitch is not None: self.zero = self.pitch
        self.vel = 0.0
        self.lift = 0.0
        self.update()

    def paintEvent(self, event):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        W,H = self.width(),self.height()
        p.fillRect(0,0,W,H,CARD_BG)
        p.setPen(QPen(BORDER,1)); p.drawRect(0,0,W-1,H-1)
        ground = H-12
        p.setPen(QPen(QColor(90,90,90),1,Qt.PenStyle.DashLine))
        p.drawLine(6,ground,W-6,ground)
        angle = 0.0 if self.pitch is None else SIDE_TOES_UP[self.side]*wrap_deg(self.pitch-self.zero)
        angle = max(-75,min(75,angle))
        s = min(W*0.5/100, (H-44)/90)
        t = QTransform()
        t.rotate(-angle)  # screen y points down, so toes up is anticlockwise
        t.scale(s,s)
        foot = t.map(self.foot)
        ankle_x = t.map(QPointF(26,0)).x()
        lift_px = self.lift/SIDE_MAX_LIFT*max(0, ground-foot.boundingRect().height()-8)
        foot.translate(W/2-ankle_x, ground-foot.boundingRect().bottom()-lift_px)
        p.fillPath(foot, QColor(228,226,220))

# ── Weight Bar ─────────────────────────────────────────────────
class WeightBar(QFrame):
    """Share of the load on each foot, as two segments that meet at the split."""

    def __init__(self):
        super().__init__()
        self.left = None  # percent on the left foot, None until both feet have data
        self.setFixedSize(440, 30)

    def set_loads(self, left, right):
        total = (left or 0)+(right or 0)
        self.left = None if left is None or right is None or total<=0 else left/total*100
        self.update()

    def paintEvent(self, event):
        p = QPainter(self)
        W,H = self.width(),self.height()
        p.fillRect(0,0,W,H,CARD_BG)
        p.setFont(QFont('Arial',11,QFont.Weight.Bold))
        if self.left is None:
            p.setPen(QPen(QColor(136,136,136)))
            p.drawText(self.rect(), Qt.AlignmentFlag.AlignCenter, "L  —  |  —  R")
            return
        right = 100-self.left
        if abs(self.left-right) <= WEIGHT_MAX_DIFF:
            lc = rc = '#1D9E75'
        elif self.left > right:
            lc, rc = '#E24B4A', '#378ADD'
        else:
            lc, rc = '#378ADD', '#E24B4A'
        split = int(W*self.left/100)
        p.fillRect(0,0,split,H,QColor(lc))
        p.fillRect(split,0,W-split,H,QColor(rc))
        p.fillRect(split-1,0,2,H,BG)
        p.setPen(QPen(Qt.GlobalColor.white))
        p.drawText(10,0,W-20,H,Qt.AlignmentFlag.AlignVCenter|Qt.AlignmentFlag.AlignLeft,f"L {self.left:.0f}%")
        p.drawText(10,0,W-20,H,Qt.AlignmentFlag.AlignVCenter|Qt.AlignmentFlag.AlignRight,f"{right:.0f}% R")

# ── Mini Chart ─────────────────────────────────────────────────
class MiniChart(QFrame):
    def __init__(self, keys, colors, y_min=None, y_max=None):
        super().__init__()
        self.keys=keys; self.colors=colors
        self.y_min=y_min; self.y_max=y_max
        self.data={k:deque([None]*MAXPTS,maxlen=MAXPTS) for k in keys}
        self.setMinimumHeight(90)
        self.setFrameShape(QFrame.Shape.NoFrame)

    def push(self, key, val):
        if key in self.data:
            self.data[key].append(val)

    def paintEvent(self, event):
        p=QPainter(self); p.setRenderHint(QPainter.RenderHint.Antialiasing)
        W,H=self.width(),self.height(); pad=6
        p.fillRect(0,0,W,H,CARD_BG)
        p.setPen(QPen(BORDER,1)); p.drawRect(0,0,W-1,H-1)
        all_v=[v for k in self.keys for v in self.data[k] if v is not None]
        if self.y_min is not None:
            lo,hi=self.y_min,self.y_max
        elif all_v:
            span=max(abs(max(all_v)),abs(min(all_v)),0.1); lo,hi=-span,span
        else:
            lo,hi=-1,1
        if lo<0<hi:
            zy=pad+(1-(0-lo)/(hi-lo))*(H-2*pad)
            p.setPen(QPen(QColor(90,90,90),1,Qt.PenStyle.DashLine))
            p.drawLine(pad,int(zy),W-pad,int(zy))
        for ki,k in enumerate(self.keys):
            c=QColor(self.colors[ki] if isinstance(self.colors,list) else self.colors[k])
            p.setPen(QPen(c,1.5))
            pts=list(self.data[k]); prev=None; n=MAXPTS
            for i,v in enumerate(pts):
                if v is None: prev=None; continue
                x=pad+i/(n-1)*(W-2*pad)
                y=pad+(1-(v-lo)/(hi-lo))*(H-2*pad)
                if prev: p.drawLine(int(prev[0]),int(prev[1]),int(x),int(y))
                prev=(x,y)
        # legend at top
        p.setFont(QFont('Arial',8))
        for ki,k in enumerate(self.keys):
            c=QColor(self.colors[ki] if isinstance(self.colors,list) else self.colors[k])
            p.setPen(QPen(c))
            p.drawText(pad+ki*36, 12, k.upper())

# ── Setup Dialog ───────────────────────────────────────────────
class SetupDialog(QDialog):
    def __init__(self, pos_l, pos_r, parent=None):
        super().__init__(parent)
        self.setWindowTitle("Setup Sensor Positions")
        self.setMinimumSize(700,500)
        self.pos = {'L':[p[:] for p in pos_l], 'R':[p[:] for p in pos_r]}
        self.current_side = 'L'
        self.current_sensor = 0

        layout = QVBoxLayout(self)

        # controls
        ctrl = QHBoxLayout()
        ctrl.addWidget(QLabel("Foot:"))
        self.foot_btn_l = QPushButton("Left"); self.foot_btn_l.setCheckable(True); self.foot_btn_l.setChecked(True)
        self.foot_btn_r = QPushButton("Right"); self.foot_btn_r.setCheckable(True)
        self.foot_btn_l.clicked.connect(lambda: self._set_foot('L'))
        self.foot_btn_r.clicked.connect(lambda: self._set_foot('R'))
        ctrl.addWidget(self.foot_btn_l); ctrl.addWidget(self.foot_btn_r)
        ctrl.addWidget(QLabel("  Sensor:"))
        self.sensor_btns = []
        for i in range(6):
            b = QPushButton(f"S{i+1}"); b.setCheckable(True)
            b.clicked.connect(lambda checked, idx=i: self._set_sensor(idx))
            ctrl.addWidget(b); self.sensor_btns.append(b)
        ctrl.addStretch()
        layout.addLayout(ctrl)
        self.sensor_btns[0].setChecked(True)

        # foot widgets
        feet = QHBoxLayout()
        self.foot_l = FootWidget('L', [list(p) for p in pos_l])
        self.foot_r = FootWidget('R', [list(p) for p in pos_r])
        self.foot_l.setup_mode = True
        self.foot_r.setup_mode = True
        self.foot_l.clicked.connect(lambda x,y: self._place('L',x,y))
        self.foot_r.clicked.connect(lambda x,y: self._place('R',x,y))
        feet.addWidget(self.foot_l); feet.addWidget(self.foot_r)
        layout.addLayout(feet)

        self.hint = QLabel("Click on the foot image to place the selected sensor.")
        self.hint.setStyleSheet("color:gray;font-size:11px")
        layout.addWidget(self.hint)

        btns = QDialogButtonBox(QDialogButtonBox.StandardButton.Save|QDialogButtonBox.StandardButton.Cancel)
        btns.accepted.connect(self.accept)
        btns.rejected.connect(self.reject)
        layout.addWidget(btns)

    def _set_foot(self, s):
        self.current_side = s
        self.foot_btn_l.setChecked(s=='L')
        self.foot_btn_r.setChecked(s=='R')

    def _set_sensor(self, idx):
        self.current_sensor = idx
        for i,b in enumerate(self.sensor_btns):
            b.setChecked(i==idx)

    def _place(self, side, x, y):
        if side != self.current_side: return
        i = self.current_sensor
        self.pos[side][i] = [x, y]
        fw = self.foot_l if side=='L' else self.foot_r
        fw.pos[i] = [x, y]
        fw.update()
        self.hint.setText(f"{side} S{i+1} placed at x={x:.1f}%, y={y:.1f}%")
        # advance
        next_s = (i+1)%6
        self._set_sensor(next_s)

    def get_positions(self):
        return self.pos['L'], self.pos['R']

# ── Foot Panel ─────────────────────────────────────────────────
class FootPanel(QWidget):
    connection_changed = pyqtSignal(bool)
    frame_received     = pyqtSignal(float, str, list, dict, object, object)  # t, side, vals, imu, seq, board_ms

    def __init__(self, side, pos_list):
        super().__init__()
        self.side = side
        self.pos = [list(p) for p in pos_list]
        self._serial_worker = None
        self._serial_thread = None
        self._ble_worker = None
        self.is_connected = False
        self.load = None  # sum of the latest pressure values
        self.zero = [0.0]*6  # subtracted from each channel before display, never from the recording
        self._recent = deque(maxlen=ZERO_WINDOW)  # raw pressure values the zero is taken from
        self._setup_ui()

    def _setup_ui(self):
        main = QVBoxLayout(self)
        main.setSpacing(8)
        main.setContentsMargins(8,8,8,8)

        # ── header ──
        hdr = QHBoxLayout()
        title = QLabel("Left foot" if self.side=='L' else "Right foot")
        title.setFont(QFont('Arial',14,QFont.Weight.Bold))
        self.status_lbl = QLabel("Disconnected")
        self.status_lbl.setStyleSheet("color:#888;font-size:12px")
        self.btn_serial = QPushButton("Serial")
        self.btn_ble    = QPushButton("BLE")
        self.btn_disc   = QPushButton("Disconnect")
        self.btn_disc.setEnabled(False)
        self.btn_disc.setStyleSheet("color:#E24B4A")
        self.btn_zero = QPushButton("Zero")
        self.btn_zero.setCheckable(True)
        self.btn_zero.setToolTip("Treat the pressure of the last second as zero. Click again to clear.")
        self.btn_zero.toggled.connect(self._toggle_zero)
        for b in [self.btn_zero, self.btn_serial, self.btn_ble, self.btn_disc]:
            b.setFont(QFont('Arial',11))
            b.setMinimumHeight(30)
        self.btn_serial.clicked.connect(self._connect_serial)
        self.btn_ble.clicked.connect(self._connect_ble)
        self.btn_disc.clicked.connect(self._disconnect)
        hdr.addWidget(title)
        hdr.addStretch()
        hdr.addWidget(self.status_lbl)
        hdr.addWidget(self.btn_zero)
        hdr.addWidget(self.btn_serial)
        hdr.addWidget(self.btn_ble)
        hdr.addWidget(self.btn_disc)
        main.addLayout(hdr)

        # ── heatmap + charts ──
        body = QHBoxLayout()
        self.foot_widget = FootWidget(self.side, self.pos)
        self.foot_widget.setMinimumWidth(160+BAR_SPACE)

        charts = QVBoxLayout()
        charts.setSpacing(6)

        # trend
        trend_box = QGroupBox("Trend"); trend_box.setFont(QFont('Arial',11))
        tl = QVBoxLayout(trend_box)
        self.pres_chart = MiniChart([f'S{i+1}' for i in range(6)], COLORS, y_min=0, y_max=3.3)
        self.pres_chart.setMinimumHeight(110)
        tl.addWidget(self.pres_chart)
        main.addWidget(trend_box)

        # side view
        side_box = QGroupBox("Foot motion"); side_box.setFont(QFont('Arial',11))
        sl = QVBoxLayout(side_box)
        self.side_view = FootSideView(self.side)
        sl.addWidget(self.side_view)
        charts.addWidget(side_box)

        # IMU
        imu_box = QGroupBox("IMU"); imu_box.setFont(QFont('Arial',11))
        il = QVBoxLayout(imu_box)
        acc_lbl = QLabel("Accelerometer"); acc_lbl.setStyleSheet("color:#888;font-size:10px;margin-top:4px")
        il.addWidget(acc_lbl)
        self.acc_chart = MiniChart(ACC_KEYS, [IMU_C[k] for k in ACC_KEYS])
        self.acc_chart.setMinimumHeight(90)
        il.addWidget(self.acc_chart)
        gyro_lbl = QLabel("Gyroscope"); gyro_lbl.setStyleSheet("color:#888;font-size:10px;margin-top:4px")
        il.addWidget(gyro_lbl)
        self.gyro_chart = MiniChart(GYRO_KEYS, [IMU_C[k] for k in GYRO_KEYS])
        self.gyro_chart.setMinimumHeight(90)
        il.addWidget(self.gyro_chart)
        charts.addWidget(imu_box)

        # both foot maps sit next to each other in the middle of the window
        if self.side == 'L':
            body.addLayout(charts)
            body.addWidget(self.foot_widget)
        else:
            body.addWidget(self.foot_widget)
            body.addLayout(charts)
        main.addLayout(body)

    # ── connection ──
    def _connect_serial(self):
        ports = [(p.device, p.description) for p in serial.tools.list_ports.comports()]
        if not ports:
            self.status_lbl.setText("No serial ports found")
            return
        dlg = QDialog(self)
        dlg.setWindowTitle("Select Serial Port")
        layout = QVBoxLayout(dlg)
        lst = QListWidget()
        for dev,desc in ports:
            lst.addItem(QListWidgetItem(f"{dev} — {desc}"))
        lst.setCurrentRow(0)
        btns = QDialogButtonBox(QDialogButtonBox.StandardButton.Ok|QDialogButtonBox.StandardButton.Cancel)
        btns.accepted.connect(dlg.accept); btns.rejected.connect(dlg.reject)
        layout.addWidget(lst); layout.addWidget(btns)
        if dlg.exec() != QDialog.DialogCode.Accepted: return
        port = ports[lst.currentRow()][0]
        self._stop_serial()
        self._serial_worker = SerialWorker(port)
        self._serial_thread = QThread()
        self._serial_worker.moveToThread(self._serial_thread)
        self._serial_worker.line_received.connect(self.parse_line)
        self._serial_worker.status.connect(self._on_status)
        self._serial_thread.started.connect(self._serial_worker.run)
        self._serial_thread.start()
        self._set_btns(True)

    def _connect_ble(self):
        self.btn_ble.setText("Scanning…"); self.btn_ble.setEnabled(False)
        self._ble_worker = BLEWorker()
        self._ble_worker.line_received.connect(self.parse_line)
        self._ble_worker.samples_received.connect(self.on_samples)
        self._ble_worker.status.connect(self._on_status)
        self._ble_worker.devices_found.connect(self._on_ble_devices)
        self._ble_worker.scan()

    def _on_ble_devices(self, devices):
        self.btn_ble.setText("BLE"); self.btn_ble.setEnabled(True)
        if not devices:
            self.status_lbl.setText("No Pressure devices found"); return
        # always show picker so user can choose
        dlg = DevicePickerDialog(devices, self)
        if dlg.exec()!=QDialog.DialogCode.Accepted or not dlg.chosen: return
        name,addr = dlg.chosen
        self.status_lbl.setText(f"Connecting {name}…")
        self._ble_worker.connect_device(addr)
        self._set_btns(True)

    def _stop_serial(self):
        if self._serial_worker: self._serial_worker.stop()
        if self._serial_thread: self._serial_thread.quit(); self._serial_thread.wait()
        self._serial_worker = None
        self._serial_thread = None

    def _disconnect(self):
        self._stop_serial()
        if self._ble_worker: self._ble_worker.stop()
        self.foot_widget.clear_cop()
        self.side_view.reset()
        self.load = None
        self._set_btns(False)
        self.status_lbl.setText("Disconnected")
        self.status_lbl.setStyleSheet("color:#888;font-size:12px")
        self.is_connected = False
        self.connection_changed.emit(False)

    def _on_status(self, msg, connected):
        color = "#1D9E75" if connected else "#888"
        self.status_lbl.setText(msg)
        self.status_lbl.setStyleSheet(f"color:{color};font-size:12px")
        if not connected:
            self._set_btns(False)
            self.load = None
        self.is_connected = connected
        self.connection_changed.emit(connected)

    def _set_btns(self, connected):
        self.btn_serial.setEnabled(not connected)
        self.btn_ble.setEnabled(not connected)
        self.btn_disc.setEnabled(connected)

    def parse_line(self, line, t):
        m = re.findall(r'S(\d+):\s*([\d.]+)', line)
        vals = None
        imu = {}
        try:
            if len(m)>=6:
                vals=[0.0]*6
                for idx,val in m:
                    i=int(idx)-1
                    if 0<=i<6: vals[i]=float(val)
            for k in IMU_KEYS:
                m2=re.search(k.upper()+r':\s*(-?[\d.]+)',line)
                if m2: imu[k]=float(m2.group(1))
        except ValueError:
            return  # corrupted line
        self.apply_snapshot(vals, imu)
        if vals is not None:
            self.frame_received.emit(t, self.side, vals, imu, None, None)

    def on_samples(self, samples, t):
        for seq, board_ms, vals, imu in samples:
            self.apply_snapshot(vals, imu)
            self.frame_received.emit(t, self.side, vals, imu, seq, board_ms)

    def _toggle_zero(self, on):
        if on and not self._recent:
            self.btn_zero.setChecked(False)
            return
        # the highest reading in the window, so its noise does not show either
        self.zero = [max(ch) for ch in zip(*self._recent)] if on else [0.0]*6

    def apply_snapshot(self, vals, imu):
        """Render a set of sensor values, whether live-parsed or replayed from a recording."""
        if vals is not None:
            self._recent.append(vals)
            vals = [max(v-z, 0.0) for v,z in zip(vals, self.zero)]
            for i,v in enumerate(vals):
                self.pres_chart.push(f'S{i+1}',v)
            self.foot_widget.update_vals(vals)
            self.load = sum(vals)
        for k,v in imu.items():
            if k in ACC_KEYS: self.acc_chart.push(k,v)
            else: self.gyro_chart.push(k,v)
        self.side_view.update_imu(imu)

    def update_pos(self, pos_list):
        self.pos = [list(p) for p in pos_list]
        self.foot_widget.pos = self.pos
        self.foot_widget.update()

# ── Main Window ────────────────────────────────────────────────
class MainWindow(QMainWindow):
    def __init__(self):
        super().__init__()
        self.setWindowTitle("Pressure Sensor Monitor")
        self.setMinimumSize(1200,800)

        central = QWidget()
        central.setStyleSheet(f"background-color: rgb({BG.red()},{BG.green()},{BG.blue()})")
        self.setCentralWidget(central)
        outer = QVBoxLayout(central)
        outer.setSpacing(6)

        # ── top bar: position setup / data storage / playback ──
        top = QHBoxLayout()
        self.btn_setup    = QPushButton("Position Setup")
        self.btn_record   = QPushButton("Record")
        self.btn_playback = QPushButton("Replay")
        for b in [self.btn_setup, self.btn_record, self.btn_playback]:
            b.setFont(QFont('Arial',11))
            b.setMinimumHeight(30)
        self.btn_record.setEnabled(False)
        self.btn_setup.clicked.connect(self.open_setup)
        self.btn_record.clicked.connect(self._toggle_record)
        self.btn_playback.clicked.connect(self._open_playback)
        top.addWidget(self.btn_setup)
        top.addWidget(self.btn_record)
        top.addWidget(self.btn_playback)
        top.addStretch()
        outer.addLayout(top)

        # ── playback scrubber (shown once a recording is loaded) ──
        self.playback_bar = QWidget()
        pb = QHBoxLayout(self.playback_bar)
        pb.setContentsMargins(0,0,0,0)
        self.btn_play = QPushButton("Play")
        self.btn_play.setFixedWidth(60)
        self.btn_play.clicked.connect(self._toggle_play)
        self.playback_slider = QSlider(Qt.Orientation.Horizontal)
        self.playback_slider.valueChanged.connect(self._slider_moved)
        self.playback_time_lbl = QLabel("0.0s / 0.0s")
        self.playback_time_lbl.setStyleSheet("color:#888;font-size:11px")
        pb.addWidget(self.btn_play)
        pb.addWidget(self.playback_slider)
        pb.addWidget(self.playback_time_lbl)
        self.playback_bar.setVisible(False)
        outer.addWidget(self.playback_bar)

        panels = QHBoxLayout()
        pos_l, pos_r = load_positions()
        self.left_panel  = FootPanel('L', pos_l)
        self.right_panel = FootPanel('R', pos_r)

        sep = QFrame(); sep.setFrameShape(QFrame.Shape.VLine)
        sep.setStyleSheet(f"color: rgb({BORDER.red()},{BORDER.green()},{BORDER.blue()})")

        panels.addWidget(self.left_panel)
        panels.addWidget(sep)
        panels.addWidget(self.right_panel)
        outer.addLayout(panels)

        self.weight_bar = WeightBar()
        outer.addWidget(self.weight_bar, alignment=Qt.AlignmentFlag.AlignHCenter)

        # ── recording state ──
        self.recording = False
        self.record_file = None
        self.record_writer = None
        self.record_start = 0.0

        # ── playback state ──
        self.playback_frames = []
        self.playback_idx = 0
        self.playback_playing = False
        self.playback_origin = 0.0
        self.playback_timer = QTimer()
        self.playback_timer.timeout.connect(self._playback_step)
        self.playback_timer.start(40)

        for panel in (self.left_panel, self.right_panel):
            panel.connection_changed.connect(self._on_connection_changed)
            panel.frame_received.connect(self._record_frame)

        # refresh timer
        self.timer = QTimer()
        self.timer.timeout.connect(self._refresh)
        self.timer.start(40)

    def _on_connection_changed(self, connected):
        if connected: self._close_playback()
        self._update_record_enabled()

    def _update_record_enabled(self):
        if self.recording: return
        self.btn_record.setEnabled(self.left_panel.is_connected or self.right_panel.is_connected)

    def _refresh(self):
        for panel in [self.left_panel, self.right_panel]:
            panel.pres_chart.update()
            panel.acc_chart.update()
            panel.gyro_chart.update()
            # panel.foot_widget.update()
        self.weight_bar.set_loads(self.left_panel.load, self.right_panel.load)
        if self.recording: self.record_file.flush()

    def open_setup(self):
        dlg = SetupDialog(self.left_panel.pos, self.right_panel.pos, self)
        if dlg.exec()==QDialog.DialogCode.Accepted:
            pl, pr = dlg.get_positions()
            self.left_panel.update_pos(pl)
            self.right_panel.update_pos(pr)
            save_positions(pl, pr)

    # ── data storage (recording) ──
    def _toggle_record(self):
        if not self.recording:
            default_name = f"recording_{time.strftime('%Y%m%d_%H%M%S')}.csv"
            path,_ = QFileDialog.getSaveFileName(self, "Save Recording", default_name, "CSV Files (*.csv)")
            if not path: return
            try:
                self.record_file = open(path, 'w', newline='')
            except OSError as e:
                QMessageBox.warning(self, "Record", f"Could not create the file:\n{e}")
                return
            self.record_writer = csv.writer(self.record_file)
            self.record_writer.writerow(RECORD_HEADER)
            self.record_start = time.perf_counter()
            self.recording = True
            self.btn_record.setText("Stop Recording")
            self.btn_record.setStyleSheet("color:#E24B4A")
        else:
            self.recording = False
            self.record_file.close()
            self.record_file = None
            self.record_writer = None
            self.btn_record.setText("Record")
            self.btn_record.setStyleSheet("")
            self._update_record_enabled()

    def _record_frame(self, t, side, vals, imu, seq, board_ms):
        if not self.recording or t < self.record_start: return
        row = [f"{t-self.record_start:.3f}", side, "" if seq is None else seq, "" if board_ms is None else board_ms]
        row += [f"{v:.4f}" for v in vals]
        row += [f"{imu[k]:.4f}" if k in imu else "" for k in IMU_KEYS]
        self.record_writer.writerow(row)

    # ── playback ──
    def _open_playback(self):
        path,_ = QFileDialog.getOpenFileName(self, "Select Replay File", "", "CSV Files (*.csv)")
        if not path: return
        try:
            frames = load_recording(path)
        except (OSError, ValueError) as e:
            QMessageBox.warning(self, "Replay", f"Could not read this file:\n{e}")
            return
        if not frames:
            QMessageBox.warning(self, "Replay", "This recording has no data.")
            return
        if self.recording: self._toggle_record()
        self.left_panel._disconnect()
        self.right_panel._disconnect()
        self.playback_frames = frames
        self.playback_idx = 0
        self._pause_playback()
        self.playback_slider.blockSignals(True)
        self.playback_slider.setMaximum(len(frames)-1)
        self.playback_slider.setValue(0)
        self.playback_slider.blockSignals(False)
        self.playback_bar.setVisible(True)
        self._playback_show(0)

    def _close_playback(self):
        self._pause_playback()
        self.playback_frames = []
        self.playback_bar.setVisible(False)

    def _pause_playback(self):
        self.playback_playing = False
        self.btn_play.setText("Play")

    def _toggle_play(self):
        if not self.playback_frames: return
        if self.playback_playing:
            self._pause_playback()
            return
        if self.playback_idx >= len(self.playback_frames)-1:
            self.playback_idx = 0
            self.left_panel.foot_widget.clear_cop()
            self.right_panel.foot_widget.clear_cop()
            self._playback_show(0)
        self.playback_origin = time.perf_counter() - self.playback_frames[self.playback_idx][0]
        self.playback_playing = True
        self.btn_play.setText("Pause")

    def _playback_step(self):
        if not self.playback_playing or not self.playback_frames: return
        target = time.perf_counter() - self.playback_origin
        last = len(self.playback_frames) - 1
        while self.playback_idx < last and self.playback_frames[self.playback_idx+1][0] <= target:
            self.playback_idx += 1
            self._playback_apply(self.playback_frames[self.playback_idx])
        self.playback_slider.blockSignals(True)
        self.playback_slider.setValue(self.playback_idx)
        self.playback_slider.blockSignals(False)
        if self.playback_idx >= last: self._pause_playback()

    def _slider_moved(self, val):
        if not self.playback_frames: return
        self.playback_idx = val
        self._pause_playback()
        self._playback_show(val)

    def _playback_show(self, idx):
        """Show the latest frame of each foot at idx, whichever foot idx itself belongs to."""
        seen = set()
        for i in range(idx, -1, -1):
            frame = self.playback_frames[i]
            if frame[1] not in seen:
                seen.add(frame[1])
                self._playback_apply(frame)
            if len(seen) == 2: break

    def _playback_apply(self, frame):
        t, side, vals, imu = frame
        panel = self.left_panel if side=='L' else self.right_panel
        panel.apply_snapshot(vals, imu)
        self.playback_time_lbl.setText(f"{t:.1f}s / {self.playback_frames[-1][0]:.1f}s")

    def closeEvent(self, event):
        if self.recording: self._toggle_record()
        self.left_panel._disconnect()
        self.right_panel._disconnect()
        super().closeEvent(event)

LEFT_B64  = ""
RIGHT_B64 = ""

def log_exception(exc_type, exc, tb):
    # without a hook PyQt6 aborts the process on an exception in a slot, losing the session
    traceback.print_exception(exc_type, exc, tb)

if __name__ == "__main__":
    sys.excepthook = log_exception
    app = QApplication(sys.argv)
    app.setStyle('Fusion')
    # dark palette
