    pal.setColor(QPalette.ColorRole.Window,        QColor(28,28,26))
    pal.setColor(QPalette.ColorRole.WindowText,    QColor(228,226,220))
    pal.setColor(QPalette.ColorRole.Base,          QColor(36,36,34))
    pal.setColor(QPalette.ColorRole.AlternateBase, QColor(44,44,42))
    pal.setColor(QPalette.ColorRole.Text,          QColor(228,226,220))
    pal.setColor(QPalette.ColorRole.Button,        QColor(44,44,42))
    pal.setColor(QPalette.ColorRole.ButtonText,    QColor(228,226,220))
    pal.setColor(QPalette.ColorRole.Highlight,     QColor(55,138,221))
    app.setPalette(pal)
    window = MainWindow()
    window.show()
    sys.exit(app.exec())